#requires -Version 7.0
$ErrorActionPreference = 'Stop'
function Get-JavaMajorVersion { $JavaVersionOutput = & java -version 2>&1; $VersionLine = $JavaVersionOutput | Select-Object -First 1; if ($VersionLine -match 'version "1\.(\d+)\.') { return [int]$Matches[1] }; if ($VersionLine -match 'version "(\d+)\.') { return [int]$Matches[1] }; throw "Java-Version konnte nicht ermittelt werden: $VersionLine" }
$ProjectRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
try { $JavaMajorVersion = Get-JavaMajorVersion; if ($JavaMajorVersion -lt 17) { throw "Gradle benoetigt JVM 17+. Aktiv ist Java $JavaMajorVersion. JAVA_HOME=$env:JAVA_HOME" }; Push-Location $ProjectRoot; if (Test-Path './gradlew.bat') { & ./gradlew.bat clean testDebugUnitTest assembleDebug --stacktrace } else { & gradle clean testDebugUnitTest assembleDebug --stacktrace }; if ($LASTEXITCODE -ne 0) { throw "Gradle build failed with exit code $LASTEXITCODE" }; $Apk = Join-Path $ProjectRoot 'app/build/outputs/apk/debug/app-debug.apk'; if (Test-Path $Apk) { Write-Host "Debug APK erstellt: $Apk" } else { throw "Build abgeschlossen, aber APK nicht gefunden: $Apk" } } catch { Write-Error $_.Exception.Message; exit 1 } finally { try { Pop-Location } catch {} }
